//! Replays the golden corpus generated by
//! `electricity/scripts/generate_http_corpus.py` -- real output from
//! CPython's own `urllib.parse.urlencode`, `plugins/base.py::
//! http_error_excerpt`, `bytes.decode("utf-8", "replace")`,
//! `urllib.request.Request`'s own header/body/URL handling,
//! `HTTPRedirectHandler.redirect_request`'s method/status matrix, and
//! `urllib.request.getproxies_environment`/`proxy_bypass_environment`
//! -- against this crate's own ports (issue #485).
//!
//! The corpus is checked in (`tests/golden/http_corpus.json`); CI
//! separately regenerates it with Python 3.11 and fails the build if
//! it differs (`.github/workflows/electricity-generated.yml`), so this
//! test only needs to trust the committed file.
//!
//! `request_header_cases`/`bytes_coercion_cases`/
//! `unknown_url_type_cases` replay through [`HttpPlugin::execute`]
//! itself rather than a private helper function: `add_headers`/
//! `python_bytes_ctor`/the scheme check are `http.rs`-internal, not
//! part of this crate's public API, and an integration test (this
//! file) only ever links against that public surface, the same
//! boundary a real embedder would see.

use electricity_tools::http_client;
use electricity_tools::{ToolCall, ToolPlugin};
use electricity_value::{CancellationToken, Dict, Value};
use serde::Deserialize;
use std::io::{Read, Write};
use std::net::TcpListener;

#[derive(Deserialize, Debug, Clone)]
#[serde(tag = "t")]
enum TaggedValue {
    #[serde(rename = "none")]
    None,
    #[serde(rename = "bool")]
    Bool { v: bool },
    #[serde(rename = "int")]
    Int { v: String },
    #[serde(rename = "float")]
    Float { bits: String },
    #[serde(rename = "str")]
    Str { v: String },
    #[serde(rename = "bytes")]
    Bytes { hex: String },
    #[serde(rename = "list")]
    List { v: Vec<TaggedValue> },
    #[serde(rename = "dict")]
    Dict { v: Vec<(TaggedValue, TaggedValue)> },
}

impl From<TaggedValue> for Value {
    fn from(tagged: TaggedValue) -> Self {
        match tagged {
            TaggedValue::None => Value::None,
            TaggedValue::Bool { v } => Value::Bool(v),
            TaggedValue::Int { v } => Value::Int(
                electricity_value::IntValue::parse_decimal(&v).expect("valid decimal integer"),
            ),
            TaggedValue::Float { bits } => {
                let bits = u64::from_str_radix(&bits, 16).expect("valid hex bit pattern");
                Value::Float(f64::from_bits(bits))
            }
            TaggedValue::Str { v } => Value::Str(v),
            TaggedValue::Bytes { hex } => Value::Bytes(decode_hex(&hex)),
            TaggedValue::List { v } => Value::List(v.into_iter().map(Value::from).collect()),
            TaggedValue::Dict { v } => {
                let mut dict = Dict::new();
                for (k, val) in v {
                    dict.insert(Value::from(k), Value::from(val));
                }
                Value::Dict(dict)
            }
        }
    }
}

fn decode_hex(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect()
}

fn load_corpus() -> serde_json::Value {
    let path =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden/http_corpus.json");
    let text = std::fs::read_to_string(path).expect("http_corpus.json exists");
    serde_json::from_str(&text).expect("valid JSON")
}

static NONE: Value = Value::None;

fn call(token: &CancellationToken) -> ToolCall<'_> {
    ToolCall {
        timeout_seconds: 5,
        config: &NONE,
        token,
        armed: false,
    }
}

fn dict_params(entries: Vec<(&str, Value)>) -> Value {
    let mut d = Dict::new();
    for (k, v) in entries {
        d.insert(Value::Str(k.to_string()), v);
    }
    Value::Dict(d)
}

fn recording_server() -> (std::net::SocketAddr, std::sync::mpsc::Receiver<Vec<u8>>) {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let addr = listener.local_addr().unwrap();
    let (tx, rx) = std::sync::mpsc::channel();
    std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().unwrap();
        let mut buf = Vec::new();
        let mut chunk = [0u8; 4096];
        // Read until the client's own `Connection: close` request is
        // fully on the wire (a short read, then nothing more for a
        // moment) -- these cases never send more than one TCP segment
        // in practice, so a brief settle read suffices. Raw bytes, not
        // a lossily-decoded `String`: `bytes_coercion_cases` sends a
        // body that is deliberately *not* valid UTF-8 (a raw byte
        // 0xff among others), and `String::from_utf8_lossy` would
        // replace it before this test ever got to compare it.
        loop {
            stream
                .set_read_timeout(Some(std::time::Duration::from_millis(100)))
                .ok();
            match stream.read(&mut chunk) {
                Ok(0) => break,
                Ok(n) => buf.extend_from_slice(&chunk[..n]),
                Err(_) => break,
            }
        }
        let _ = tx.send(buf);
        let _ = stream
            .write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok");
    });
    (addr, rx)
}

#[test]
fn urlencode_cases_match_cpython() {
    let corpus = load_corpus();
    for case in corpus["urlencode_cases"].as_array().unwrap() {
        let doseq = case["doseq"].as_bool().unwrap();
        let pairs: Vec<(String, Value)> = case["params"]
            .as_array()
            .unwrap()
            .iter()
            .map(|pair| {
                let key = pair[0].as_str().unwrap().to_string();
                let tagged: TaggedValue = serde_json::from_value(pair[1].clone()).unwrap();
                (key, Value::from(tagged))
            })
            .collect();
        let expected = case["expected"].as_str().unwrap();
        let actual = electricity_value::pycompat::urlencode(&pairs, doseq).unwrap();
        assert_eq!(actual, expected, "case: {case:?}");
    }
}

#[test]
fn http_error_excerpt_cases_match_circuitry() {
    let corpus = load_corpus();
    for case in corpus["http_error_excerpt_cases"].as_array().unwrap() {
        let body = case["body"].as_str().unwrap();
        let expected = case["expected"].as_str().unwrap();
        let actual = electricity_tools::http::http_error_excerpt(body, 500);
        assert_eq!(actual, expected, "case: {case:?}");
    }
}

#[test]
fn utf8_replace_cases_match_cpython() {
    let corpus = load_corpus();
    for case in corpus["utf8_replace_cases"].as_array().unwrap() {
        let hex = case["hex"].as_str().unwrap();
        let bytes = decode_hex(hex);
        let expected = case["expected"].as_str().unwrap();
        let actual = String::from_utf8_lossy(&bytes);
        assert_eq!(actual, expected, "hex: {hex}");
    }
}

#[test]
fn redirect_reason_cases_match_urllibs_own_text() {
    let corpus = load_corpus();
    for case in corpus["redirect_reason_cases"].as_array().unwrap() {
        let expected = case["reason"].as_str().unwrap();
        let actual = match case["case"].as_str().unwrap() {
            "disallowed_scheme" => electricity_tools::http::disallowed_redirect_scheme_reason(
                "Found",
                "javascript:alert(1)",
            ),
            "max_repeats" | "max_redirections" => {
                electricity_tools::http::redirect_loop_reason("Found")
            }
            other => panic!("unexpected case name {other:?}"),
        };
        assert_eq!(actual, expected, "case: {case:?}");
    }
}

#[test]
fn redirect_decision_cases_match_urllibs_own_matrix() {
    let corpus = load_corpus();
    for case in corpus["redirect_decision_cases"].as_array().unwrap() {
        let method = case["method"].as_str().unwrap();
        let status = case["status"].as_u64().unwrap() as u16;
        let followed = case["followed"].as_bool().unwrap();
        let expected_new_method = case["new_method"].as_str();
        let decision = http_client::redirect_policy(method, status);
        assert_eq!(decision.is_some(), followed, "case: {case:?}");
        if let Some(decision) = decision {
            assert_eq!(
                Some(decision.method.as_str()),
                expected_new_method,
                "case: {case:?}"
            );
        }
    }
}

#[test]
fn proxy_env_cases_match_urllibs_own_convention() {
    let corpus = load_corpus();
    for case in corpus["proxy_env_cases"].as_array().unwrap() {
        let env: Vec<(String, String)> = case["env"]
            .as_array()
            .unwrap()
            .iter()
            .map(|pair| {
                (
                    pair[0].as_str().unwrap().to_string(),
                    pair[1].as_str().unwrap().to_string(),
                )
            })
            .collect();
        let proxies = http_client::getproxies_environment(&env);
        let proxies_map: std::collections::BTreeMap<String, String> = proxies.into_iter().collect();
        let expected_proxies: std::collections::BTreeMap<String, String> = case["proxies"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
            .collect();
        assert_eq!(proxies_map, expected_proxies, "case: {case:?}");

        for (host, expected_bypass) in case["bypass"].as_object().unwrap() {
            let bypassed = http_client::proxy_bypass_environment(
                &proxies_map
                    .iter()
                    .map(|(k, v)| (k.clone(), v.clone()))
                    .collect::<Vec<_>>(),
                host,
            );
            assert_eq!(
                bypassed,
                expected_bypass.as_bool().unwrap(),
                "host {host} in case: {case:?}"
            );
        }
    }
}

#[tokio::test]
async fn unknown_url_type_cases_match_pythons_valueerror() {
    let corpus = load_corpus();
    let token = CancellationToken::new();
    for case in corpus["unknown_url_type_cases"].as_array().unwrap() {
        let url = case["url"].as_str().unwrap();
        let expected_error = case["error"].as_str();
        // A case with no expected parse-time `ValueError` carries a
        // *valid* scheme (`http`/`https`/`ftp`/relative) -- this
        // corpus section only pins the scheme check itself, never
        // what happens afterward, and several of its own URLs
        // (`http://example.com/x`, `https://example.com/x`) name a
        // real external host. Running `execute` on those would be a
        // real DNS lookup/connection attempt (this lane's own
        // network-isolation rule, issue #485) --
        // skip the call entirely rather than let it reach the
        // network only to discard the result.
        let Some(message) = expected_error else {
            continue;
        };
        let result = electricity_tools::http::HttpPlugin
            .execute(
                dict_params(vec![("url", Value::Str(url.to_string()))]),
                &call(&token),
            )
            .await;
        let err = result.expect_err("expected a ValueError");
        assert_eq!(err.message, message, "case: {case:?}");
    }
}

#[tokio::test]
async fn bytes_coercion_cases_match_pythons_bytes_ctor() {
    let corpus = load_corpus();
    let token = CancellationToken::new();
    for case in corpus["bytes_coercion_cases"].as_array().unwrap() {
        let tagged: TaggedValue = serde_json::from_value(case["value"].clone()).unwrap();
        let value: Value = tagged.into();
        // `str` isn't part of `bytes(body)`'s own coercion matrix
        // `plugins/http.py` reaches through `body:` (a `str` body is
        // UTF-8 encoded directly, never passed to `bytes()` at all);
        // `None` is never reached either (`params.get("body") is not
        // None` gates the call itself, in both this port and the
        // reference -- this corpus section's own `None` case checks
        // `bytes(None)` in isolation, a call neither ever actually
        // makes). Skip both; this case list is for the branch that
        // actually is reachable from a real `body:` value.
        if matches!(value, Value::Str(_) | Value::None) {
            continue;
        }
        let (addr, rx) = recording_server();
        let result = electricity_tools::http::HttpPlugin
            .execute(
                dict_params(vec![
                    ("url", Value::Str(format!("http://{addr}/"))),
                    ("method", Value::Str("POST".to_string())),
                    ("body", value),
                ]),
                &call(&token),
            )
            .await;
        match case["error"].as_str() {
            Some(expected_class) => {
                let err = result.expect_err("expected a coercion failure");
                assert_eq!(err.py_class.name(), expected_class, "case: {case:?}");
                if let Some(expected_message) = case["error_message"].as_str() {
                    assert_eq!(err.message, expected_message, "case: {case:?}");
                }
            }
            None => {
                result.expect("expected a successful send");
                let request_bytes = rx.recv().unwrap();
                let separator = b"\r\n\r\n";
                let body_start = request_bytes
                    .windows(separator.len())
                    .position(|w| w == separator)
                    .map(|i| i + separator.len())
                    .unwrap_or(request_bytes.len());
                let sent_hex = request_bytes[body_start..]
                    .iter()
                    .map(|b| format!("{b:02x}"))
                    .collect::<String>();
                assert_eq!(sent_hex, case["result"].as_str().unwrap(), "case: {case:?}");
            }
        }
    }
}

#[tokio::test]
async fn request_header_cases_keep_every_user_header_capitalize_collapsed() {
    let corpus = load_corpus();
    let token = CancellationToken::new();
    for case in corpus["request_header_cases"].as_array().unwrap() {
        let headers_in = case["headers_in"].as_array().unwrap();
        if headers_in.is_empty() {
            continue;
        }
        let mut headers_dict = Dict::new();
        for pair in headers_in {
            headers_dict.insert(
                Value::Str(pair[0].as_str().unwrap().to_string()),
                Value::Str(pair[1].as_str().unwrap().to_string()),
            );
        }
        let (addr, rx) = recording_server();
        electricity_tools::http::HttpPlugin
            .execute(
                dict_params(vec![
                    ("url", Value::Str(format!("http://{addr}/"))),
                    ("headers", Value::Dict(headers_dict)),
                ]),
                &call(&token),
            )
            .await
            .expect("expected a successful send");
        let request_bytes = rx.recv().unwrap();
        let request_text = String::from_utf8_lossy(&request_bytes).to_string();
        let sent_lines: Vec<(String, String)> = request_text
            .split("\r\n")
            .skip(1)
            .take_while(|line| !line.is_empty())
            .filter_map(|line| line.split_once(':'))
            .map(|(k, v)| (k.to_lowercase(), v.trim().to_lowercase()))
            .collect();
        let expected: Vec<(String, String)> = case["header_items"]
            .as_array()
            .unwrap()
            .iter()
            .map(|pair| {
                (
                    pair[0].as_str().unwrap().to_lowercase(),
                    pair[1].as_str().unwrap().to_lowercase(),
                )
            })
            .collect();
        // Every *name* `header_items` names (capitalize-collapsed) is
        // the complete, deduplicated final state for that name -- not
        // just a line to find somewhere in the request. Comparing the
        // *whole* set of lines under those names, not a `contains`
        // check on each expected line individually, catches the case
        // `contains` alone would pass: a lingering *second* line under
        // the same name with the user's own, now-overwritten value
        // still on the wire alongside the correct one (issue #485's
        // review, "weak assertions" case -- `contains` can't
        // tell "exactly this one line" apart from "this line, plus
        // another the collapse should have erased").
        let expected_names: std::collections::BTreeSet<&str> =
            expected.iter().map(|(k, _)| k.as_str()).collect();
        let actual_for_names: Vec<&(String, String)> = sent_lines
            .iter()
            .filter(|(k, _)| expected_names.contains(k.as_str()))
            .collect();
        for (name, value) in &expected {
            let matches = actual_for_names
                .iter()
                .filter(|(k, v)| k == name && v == value)
                .count();
            assert_eq!(
                matches, 1,
                "expected exactly one {name}: {value} line, found {matches} in request:\n{request_text}"
            );
        }
        assert_eq!(
            actual_for_names.len(),
            expected.len(),
            "expected exactly {expected:?} under these names, found {actual_for_names:?} in request:\n{request_text}"
        );
    }
}

fn read_full_request(stream: &mut std::net::TcpStream) -> Vec<u8> {
    stream
        .set_read_timeout(Some(std::time::Duration::from_secs(3)))
        .ok();
    let mut buf = Vec::new();
    let mut chunk = [0u8; 4096];
    loop {
        match stream.read(&mut chunk) {
            Ok(0) => break,
            Ok(n) => {
                buf.extend_from_slice(&chunk[..n]);
                if let Some(pos) = buf.windows(4).position(|w| w == b"\r\n\r\n") {
                    let header_text = String::from_utf8_lossy(&buf[..pos]);
                    let content_length: usize = header_text
                        .lines()
                        .find_map(|l| {
                            let (name, value) = l.split_once(':')?;
                            if name.trim().eq_ignore_ascii_case("content-length") {
                                value.trim().parse::<usize>().ok()
                            } else {
                                None
                            }
                        })
                        .unwrap_or(0);
                    if buf.len() - (pos + 4) >= content_length {
                        break;
                    }
                }
            }
            Err(_) => break,
        }
    }
    buf
}

/// Drives a single accepted connection through *steps* -- each
/// `(chunk, delay_seconds)` pair sleeps first, when asked, then
/// writes *chunk*; an empty *chunk* closes the connection without
/// writing anything. Mirrors `generate_http_corpus.py`'s own
/// `_respond_steps` exactly, replaying the very bytes
/// `end_to_end_cases` recorded rather than a hand-copied duplicate of
/// them.
fn serve_steps(steps: Vec<(Vec<u8>, f64)>) -> std::net::SocketAddr {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let addr = listener.local_addr().unwrap();
    std::thread::spawn(move || {
        let (mut stream, _) = listener.accept().unwrap();
        read_full_request(&mut stream);
        for (chunk, delay) in steps {
            if delay > 0.0 {
                std::thread::sleep(std::time::Duration::from_secs_f64(delay));
            }
            if chunk.is_empty() {
                drop(stream);
                return;
            }
            let _ = stream.write_all(&chunk);
        }
    });
    addr
}

#[tokio::test]
async fn end_to_end_cases_match_cpython() {
    let corpus = load_corpus();
    let token = CancellationToken::new();
    for case in corpus["end_to_end_cases"].as_array().unwrap() {
        let name = case["case"].as_str().unwrap();

        if name == "content_type_json_setdefault_collision" {
            let (addr, rx) = recording_server();
            let mut body = Dict::new();
            body.insert(Value::Str("a".to_string()), Value::from(1i64));
            let mut headers = Dict::new();
            headers.insert(
                Value::Str("content-type".to_string()),
                Value::Str("text/plain".to_string()),
            );
            electricity_tools::http::HttpPlugin
                .execute(
                    dict_params(vec![
                        ("url", Value::Str(format!("http://{addr}/"))),
                        ("method", Value::Str("POST".to_string())),
                        ("headers", Value::Dict(headers)),
                        ("json", Value::Dict(body)),
                    ]),
                    &call(&token),
                )
                .await
                .expect("expected a successful send");
            let request_text = String::from_utf8_lossy(&rx.recv().unwrap()).to_string();
            for line in case["request_header_lines"].as_array().unwrap() {
                let line = line.as_str().unwrap();
                // `User-Agent` differs by design (issue #485's own
                // settled question); `Host` carries this test's own
                // real port, never the corpus's `__PORT__` placeholder.
                if line.starts_with("User-Agent:") || line.starts_with("Host:") {
                    continue;
                }
                assert!(
                    request_text.contains(line),
                    "expected line {line:?} in request:\n{request_text}"
                );
            }
            continue;
        }

        let steps: Vec<(Vec<u8>, f64)> = case["response_steps"]
            .as_array()
            .unwrap()
            .iter()
            .map(|step| {
                let hex = step[0].as_str().unwrap();
                let delay = step[1].as_f64().unwrap();
                (decode_hex(hex), delay)
            })
            .collect();
        let addr = serve_steps(steps);

        let mut params_vec = vec![("url", Value::Str(format!("http://{addr}/")))];
        if let Some(method) = case["params"].get("method").and_then(|v| v.as_str()) {
            params_vec.push(("method", Value::Str(method.to_string())));
        }
        let timeout_seconds = case["timeout_seconds"].as_u64().unwrap() as u32;
        let call_with_timeout = ToolCall {
            timeout_seconds,
            config: &NONE,
            token: &token,
            armed: false,
        };
        let result = electricity_tools::http::HttpPlugin
            .execute(dict_params(params_vec), &call_with_timeout)
            .await;

        match case["raised"].as_str() {
            Some(expected_class) => {
                let err = result.expect_err("expected a raised failure");
                assert_eq!(err.py_class.name(), expected_class, "case: {name}");
                assert_eq!(
                    err.message,
                    case["message"].as_str().unwrap(),
                    "case: {name}"
                );
            }
            None => {
                let result = result.expect("expected a returned result");
                assert_eq!(result.ok, case["ok"].as_bool().unwrap(), "case: {name}");
                assert_eq!(
                    result.stderr.as_deref(),
                    case["stderr"].as_str(),
                    "case: {name}"
                );
                let expected_value = case["value"].as_str().unwrap();
                assert_eq!(
                    result.value,
                    Value::Str(expected_value.to_string()),
                    "case: {name}"
                );
                let raw = result.raw.as_dict().unwrap();
                let status = raw.get(&Value::Str("status".to_string())).unwrap();
                assert_eq!(
                    status,
                    &Value::from(case["raw"]["status"].as_i64().unwrap()),
                    "case: {name}"
                );
                let url = raw.get(&Value::Str("url".to_string())).unwrap().py_str();
                let expected_url = case["raw"]["url"]
                    .as_str()
                    .unwrap()
                    .replace("__PORT__", &addr.port().to_string());
                assert_eq!(url, expected_url, "case: {name}");
                let headers_dict = raw
                    .get(&Value::Str("headers".to_string()))
                    .unwrap()
                    .as_dict()
                    .unwrap();
                for (k, v) in case["raw"]["headers"].as_object().unwrap() {
                    let actual = headers_dict.get(&Value::Str(k.clone())).map(|v| v.py_str());
                    assert_eq!(actual.as_deref(), v.as_str(), "header {k} in case: {name}");
                }
            }
        }
    }
}
